# easy-host bash completion
#
# Generated by scripts/generate-completions.ts from the commander command
# definitions. Do not edit this file by hand; regenerate it instead.
#
# Install: copy this file to
#   ${XDG_DATA_HOME:-$HOME/.local/share}/bash-completion/completions/easy-host
# or source it from ~/.bashrc.

_easy_host() {
  local cur prev cmd i skip
  COMPREPLY=()
  cur="${COMP_WORDS[COMP_CWORD]}"
  prev="${COMP_WORDS[COMP_CWORD-1]}"
  cmd=""
  skip=0

  for ((i = 1; i < COMP_CWORD; i++)); do
    if ((skip)); then
      skip=0
      continue
    fi
    case "${COMP_WORDS[i]}" in
      --local|--name|--ref|--port|--container-port|--bind|--env-file|--health-path|--probe|--volume|--tail)
        skip=1
        ;;
      add|list|status|logs|update|rollback|remove|config|doctor|version)
        if [[ -z "$cmd" ]]; then
          cmd="${COMP_WORDS[i]}"
        fi
        ;;
    esac
  done

  if [[ -z "$cmd" ]]; then
    if [[ "$cur" == -* ]]; then
      COMPREPLY=( $(compgen -W "--json -h --help" -- "$cur") )
    else
      COMPREPLY=( $(compgen -W "add list status logs update rollback remove config doctor version" -- "$cur") )
    fi
    return 0
  fi

  if [[ "$cur" == -* ]]; then
    case "$cmd" in
      add)
        COMPREPLY=( $(compgen -W "--local --name --ref --port --container-port --bind --env-file --health-path --probe --volume --yes --json -h --help" -- "$cur") )
        ;;
      list)
        COMPREPLY=( $(compgen -W "--json -h --help" -- "$cur") )
        ;;
      status)
        COMPREPLY=( $(compgen -W "--json -h --help" -- "$cur") )
        ;;
      logs)
        COMPREPLY=( $(compgen -W "-f --follow --tail -h --help" -- "$cur") )
        ;;
      update)
        COMPREPLY=( $(compgen -W "--rebuild --json -h --help" -- "$cur") )
        ;;
      rollback)
        COMPREPLY=( $(compgen -W "--json -h --help" -- "$cur") )
        ;;
      remove)
        COMPREPLY=( $(compgen -W "--volumes --yes --force --json -h --help" -- "$cur") )
        ;;
      config)
        COMPREPLY=( $(compgen -W "--path --edit --json -h --help" -- "$cur") )
        ;;
      doctor)
        COMPREPLY=( $(compgen -W "--json -h --help" -- "$cur") )
        ;;
      version)
        COMPREPLY=( $(compgen -W "--json -h --help" -- "$cur") )
        ;;
    esac
    return 0
  fi

  case "$cmd" in
    add)
      case "$prev" in
        --local|--env-file)
          COMPREPLY=( $(compgen -f -- "$cur") )
          ;;
        --probe)
          COMPREPLY=( $(compgen -W "http tcp" -- "$cur") )
          ;;
      esac
      ;;
  esac

  return 0
}

complete -F _easy_host easy-host
